async function addFiles(fs:FileList|null){if(!fs||!gate())return;if(Array.from(fs).some(f=>!f.type.startsWith('image/')))return notify('Use the Video button to upload videos.');setBusy('Uploading…');await run(async()=>{const added:any[]=[];for(const f of Array.from(fs))added.push(await upload(f));setMedia(m=>[...m,...added])});setBusy('')}
