async function like(p:any){if(!gate()||liking.current.has(p.id))return;if(p.id.startsWith('sample'))return notify('Sample post. Share the first real community moment!');liking.current.add(p.id);try{const action=crypto.randomUUID(),d=await api('like',{post:p.id,id:action});setPostCounts(v=>({...v,[p.id]:{...v[p.id],likes:d.likes,liked:true}}));notify('Liked. '+(JSON.parse(p.media||'[]').some((m:any)=>m?.type==='image'||m?.type==='video')?10:4)+' points transferred to the post owner.');await load()}catch(e:any){notify(e.message)}finally{liking.current.delete(p.id)}}async function openComments(p:any){if(!gate())return;if(p.id.startsWith('sample'))return notify('Comments open on real community posts.');setSelected(p);setModal('comments');setReply(null);await run(async()=>setComments(await api('comments?post='+p.id)))}async function share(p?:any){if(!gate())return;await run(async()=>{const url=location.origin+(p?'/?post='+encodeURIComponent(p.id):'/tv/'+(data.tv[tvIndex]?.id||'show'));if(navigator.share)await navigator.share({title:p?'A moment on eConect':'eConect TV',url});else{await navigator.clipboard.writeText(url);notify('Share link copied.')}})}function gift(p:any,k='gift'){if(!gate())return;if(data.androidPreview)return notify('Purchases and gifts are not enabled in this Android preview.');checkoutId.current=crypto.randomUUID();if(p?.id?.startsWith('demo'))return notify('Gifts are available for registered members. This is a sample profile.');setSelected(p||me);setKind(k);setPack(1);setPayment(null);setSource(k==='topup'||k==='vote'||data.paystackEnabled?'bank':'wallet');setModal('gift')}async function purchase(){setBusy('Processing…');await run(async()=>{if(source==='wallet'&&kind!=='topup'){await api('gift',{recipient:selected.id,coins:pack,kind,coinPrice});setModal('');notify(`${pack} eCoin sent successfully.`);await load()}else if(data.paystackEnabled){const d=await api('paystack/initialize',{id:checkoutId.current,kind:'payment',action:kind,recipient:selected.id,coins:pack,coinPrice});if(d.authorization_url)location.assign(d.authorization_url);else{notify('Payment already confirmed.');await load()}}else setPayment(await api('payment',{recipient:selected.id,coins:pack,kind,coinPrice}))});setBusy('')}
async function startChat(p:any){if(!gate())return;if(p.id.startsWith('demo'))return notify('Invite a friend to start a real conversation. This is a sample member.');await run(async()=>{const c=await api('chat',{recipient:p.id});setChat({...c,person:p});seen.current.clear();setModal('');setPage('Messages');setChats(await api('chats'));setChatData(await api('messages?id='+c.id))})}async function openInquiry(conversation:string,person:any){seen.current.clear();setChatData(null);if(attachment?.preview)URL.revokeObjectURL(attachment.preview);setAttachment(null);setChat({id:conversation,person});setModal('');setPage('Messages');await run(async()=>{setChats(await api('chats'));setChatData(await api('messages?id='+encodeURIComponent(conversation)))})}
async function sendChatMedia(){if(!attachment||!chat||busy)return;const a=attachment,targetReply=chatReply;if(a.conversation!==chat.id)return notify('Choose the file again for this conversation.');setBusy('Sending…');try{let url=a.url;if(!url){url=(await upload(a.file,'chat',chat.id)).url;setAttachment((v:any)=>v&&v.id===a.id?{...v,url}:v)}await api('message',{conversation:chat.id,kind:a.kind,body:url,messageId:a.id,replyTo:targetReply?.id});setChatReply((current:any)=>current?.id===targetReply?.id?null:current);URL.revokeObjectURL(a.preview);setAttachment(null);await refreshChat();await load();notify((a.kind==='image'?10:20)+' points transferred to the recipient.')}catch(e:any){notify(e.message)}finally{setBusy('')}}
async function refreshChat(){const chatId=chat.id,d=await api('messages?id='+chatId);if(activeChat.current!==chatId)return;if(d.conversation.id!==chatId){setChat((current:any)=>current?.id===chatId?{...current,id:d.conversation.id}:current);setChatData(d);return}setChatData(d);if(document.visibilityState==='visible'){await api('messages-read',{conversation:chatId,through:d.readThrough});await refreshUnread()}}
useEffect(()=>{if(page!=='Messages'||!me)return;let live=true;const refresh=()=>api('chats').then(rows=>{if(live)setChats(rows)}).catch(()=>{});refresh();const t=setInterval(refresh,5000);return()=>{live=false;clearInterval(t)}},[page,me?.id]);
useEffect(()=>{if(page!=='Messages'||!chat)return;refreshChat().catch(()=>{});const t=setInterval(()=>refreshChat().catch(()=>{}),2500);return()=>clearInterval(t)},[page,chat?.id,me?.id]);
async function callUser(video:boolean){await calls.start(chat.id,chat.person,video)}async function endCall(){await calls.hangup()}
async function record(){if(recording)return;await run(async()=>{const s=await navigator.mediaDevices.getUserMedia({audio:true}),r=new MediaRecorder(s),chunks:Blob[]=[];rec.current=r;recTime.current=Date.now();r.ondataavailable=e=>chunks.push(e.data);r.onstop=()=>{s.getTracks().forEach(t=>t.stop());setRecording(false);const b=new Blob(chunks,{type:r.mimeType});setVoice({blob:b,url:URL.createObjectURL(b),duration:Math.min(1800,Math.max(1,Math.ceil((Date.now()-recTime.current)/1000)))})};r.start();setRecording(true);setTimeout(()=>{if(r.state==='recording')r.stop()},1800000)})}async function sendVoice(){const targetReply=chatReply;setBusy('Sending…');await run(async()=>{const u=await upload(new File([voice.blob],'voice.webm',{type:voice.blob.type}),'voice');await api('message',{conversation:chat.id,kind:'voice',body:u.url,duration:voice.duration,replyTo:targetReply?.id});setChatReply((current:any)=>current?.id===targetReply?.id?null:current);setVoice(null);await refreshChat();await load()});setBusy('')}
useEffect(()=>{if(!me?.id)return;const refresh=()=>api('balance').then(b=>{setData((d:any)=>({...d,me:{...d.me,balance:b.balance,bonus:b.bonus}}));setWallet((w:any)=>({...w,balance:b.balance,bonus:b.bonus,total:b.total}))}).catch(()=>{});const onVisible=()=>{if(document.visibilityState==='visible')refresh()};const timer=setInterval(refresh,20000);document.addEventListener('visibilitychange',onVisible);return()=>{clearInterval(timer);document.removeEventListener('visibilitychange',onVisible)}},[me?.id]);
function openShop(username:string){setShop(username);setMarketProduct('');setModal('');go('Marketplace')}
function openMarketProduct(id:string){setMarketProduct(id);if(id){setPage('Marketplace')}}
const nav=[['Home',Home],['Marketplace',ShoppingBag],['Investment',WealthIcon],['Discover',Compass],['eConect TV',Radio],['Messages',MessageCircle],['Wallet',Wallet],['Notifications',Bell]]as const;
function searchBar(phone:boolean){return <div className={'search-box '+(phone?'phone-search':'desktop-search')}>{!phone&&<Search size={18}/>}<input placeholder="Search people, posts and inspiration" value={query} autoComplete="off" onFocus={()=>setSuggestionsOpen(true)} onKeyDown={e=>{if(e.key==='Escape')setSuggestionsOpen(false);if(e.key==='Enter'){setSuggestionsOpen(false);go('Home')}}} onChange={e=>{setSuggestions({members:[],posts:[],hashtags:[]});setQuery(e.target.value);setSuggestionsOpen(true);setPage('Home')}}/><button aria-label="Search eConect" onClick={()=>{setSuggestionsOpen(false);go('Home')}}><Search size={16}/></button><SearchSuggestions/></div>}
function SearchSuggestions(){if(!suggestionsOpen||!query.trim()||!(suggestions.members.length||suggestions.posts.length||suggestions.hashtags.length))return null;function showResults(term:string){setQuery(term);setSuggestionsOpen(false);setModal('');setPage('Home')}return <div className="search-suggestions" aria-label="Search suggestions">{suggestions.members.length>0&&<><div className="suggestion-heading">People</div>{suggestions.members.map((p:any)=><button type="button" key={p.id} onClick={()=>{setSuggestionsOpen(false);setQuery('');profile(p)}}>{p.avatar?<img src={p.avatar} alt=""/>:<span className="suggestion-initial">{p.name?.[0]||'e'}</span>}<span><strong>{p.name} {p.surname}</strong><small>@{p.username}</small></span></button>)}</>}{suggestions.posts.length>0&&<><div className="suggestion-heading">Posts</div>{suggestions.posts.map((p:any)=><button type="button" key={p.id} onClick={()=>showResults(p.body.slice(0,80))}><span><strong>{p.body.slice(0,80)}{p.body.length>80?'…':''}</strong><small>Post by {p.name} {p.surname} · @{p.username}</small></span></button>)}</>}{suggestions.hashtags.length>0&&<><div className="suggestion-heading">Hashtags</div>{suggestions.hashtags.map((tag:string)=><button type="button" key={tag} onClick={()=>showResults(tag)}><strong>{tag}</strong></button>)}</>}</div>}
function renderMembers(){return <section className="member-section"><div className="section-title"><div><h3>Find eConect members <i className="dot"/></h3><p>A familiar face. A brand new connection.</p></div><button className="text-button" onClick={()=>go('Discover')}>View all <ArrowRight size={14}/></button></div><div className="member-strip">{members.filter((p:any)=>p.id!==me?.id&&!hidden.includes(p.id)).slice(0,5).map((p:any)=><div className="member-tile" key={p.id}><Avatar p={p} size={62} click={()=>profile(p)} badge={personUnread(p.id)}/><strong>{p.name}</strong><small>@{p.username.split('_')[0]}</small><div className="member-actions"><button className="yes" title="View profile" onClick={()=>profile(p)}><Check size={14}/></button><button className="no" title="Skip member" onClick={()=>setHidden([...hidden,p.id])}><X size={13}/></button></div></div>)}</div></section>}
function renderPost(p:any){p={...p,...postCounts[p.id]};const files=JSON.parse(p.media);return <article key={p.id} className="post card" id={'post-'+p.id}><div className="post-head"><Avatar p={p} click={()=>profile({...p,id:p.user})} badge={personUnread(p.user)}/><div><button className="name-button" onClick={()=>profile({...p,id:p.user})}>{p.name} {p.surname}<ShieldCheck size={13}/></button><small>@{p.username} <span>·</span> {p.created==='Sample'?'Community preview':new Date(p.created+'Z').toLocaleDateString(undefined,{month:'short',day:'numeric'})} <Globe size={11}/></small></div><button className="icon-button more" aria-label="Post options" onClick={()=>{setSelected(p);setModal('post-options')}}><MoreHorizontal size={20}/></button></div><p className="post-body">{p.body}</p>{files.length>0&&<div className={'post-media '+(files.length>1?'multi':'')}>{files.slice(0,4).map((m:any,i:number)=><div className="post-media-tile" key={i}>{m.type==='video'?<PostVideo src={m.url} poster={m.poster} onOpen={()=>{setSelected({items:files,index:i});setModal('image')}}/>:<button aria-label={i===3&&files.length>4?'View '+(files.length-3)+' more photos and videos':'Open media '+(i+1)} onClick={()=>{setSelected({items:files,index:i});setModal('image')}}><img src={m.url} alt="Community photo" loading="lazy"/>{i===3&&files.length>4&&<span className="media-more">+{files.length-4}</span>}</button>}{m.type==='video'&&i===3&&files.length>4&&<button className="video-media-more" onClick={()=>{setSelected({items:files,index:i});setModal('image')}} aria-label="View more media">+{files.length-4}</button>}</div>)}</div>}<div className="post-stats"><span><i className="mini-heart"><Heart size={10} fill="currentColor"/></i>{p.likes||'Be the first to like'}</span><button onClick={()=>openComments(p)}>{p.comments||0} comments</button></div><div className="post-actions"><span className="post-like-control"><button title={'Each like: '+(files.some((m:any)=>m?.type==='image'||m?.type==='video')?10:4)+' points transferred to the post owner'} onClick={()=>like(p)}><Heart size={18} fill={p.liked?'currentColor':'none'}/> Like</button>{me&&p.user===me.id&&<LikeFlight people={likeEvents.filter((e:any)=>e.post===p.id).slice(0,30)}/>}</span><button onClick={()=>openComments(p)}><MessageCircle size={18}/> Comment</button><button onClick={()=>share(p)}><Share2 size={17}/> Share</button></div></article>}
