{page==='Discover'&&<><Heading title="Find your people." sub="Turn a new face into a familiar one."/><div className="discover-grid">{members.filter((p:any)=>(p.name+' '+p.username).toLowerCase().includes(query.toLowerCase())).map((p:any)=><article className="discover-card card" key={p.id}><div className="discover-cover"/><Avatar p={p} size={72} click={()=>profile(p)} badge={personUnread(p.id)}/><h3>{p.name} {p.surname}</h3><small>@{p.username}</small><p>{p.bio||'New to eConect. Say hello!'}</p><span className="location"><Globe size={13}/>{p.city}, {p.country}</span><button className="secondary" onClick={()=>profile(p)}>View profile <ArrowUpRight size={15}/></button></article>)}</div></>}
{page==='Profile'&&profilePage&&<><div className="profile-page card"><div className="profile-balance-cover"><section className="remaining-balance profile-balance" aria-label="Profile eCoin balance"><div className="remaining-icon"><Coin/></div><div className="remaining-amount"><span>eCOIN BALANCE</span><strong>{coins(total(profileBalance))} <small>eCoin</small><i>·</i><b>{total(profileBalance).toLocaleString()} points</b></strong>{profilePage.id===me?.id&&<p>{coins(me.balance||0)} withdrawable · {coins(me.bonus||0)} bonus eCoin</p>}</div>{profilePage.id===me?.id?<button className="primary add-ecoin" onClick={()=>gift(me,'topup')}><Plus size={16}/> Add eCoin</button>:<button className="primary" onClick={()=>gift(profilePage)}><Gift size={16}/> Gift eCoin</button>}</section></div><div className="profile-summary"><Avatar p={profilePage} size={88} badge={personUnread(profilePage.id)}/><h2>{profilePage.name} {profilePage.surname}</h2><p className="muted">@{profilePage.username} · {profilePage.city||'eConect'}, {profilePage.country||'Community'}</p><p>{profilePage.bio||'A new face in the eConect community.'}</p><div className="profile-level">Level {Math.floor(total(profileBalance)/1000)+1}</div><ShopButton username={profilePage.username} onClick={openShop}/><div className="profile-buttons">{profilePage.id===me?.id?<><button className="primary" onClick={()=>{setSelected(me);setModal('edit-profile')}}><Settings size={16}/> Edit profile</button><button className="secondary" onClick={()=>{setModal('');go('Wallet')}}><Wallet size={16}/> My wallet</button></>:<><button className="primary" onClick={()=>startChat(profilePage)}><MessageCircle size={16}/> Start conversation</button><button className="secondary" onClick={()=>gift(profilePage)}><Gift size={16}/> Gift eCoin</button><button className="round-button" title="Audio call conversation" onClick={()=>startChat(profilePage)}><Phone size={17}/></button><button className="round-button" title="Video call conversation" onClick={()=>startChat(profilePage)}><Video size={18}/></button></>}</div>{profilePage.id.startsWith('demo')&&<div className="preview-note">Sample profile · Preview the community experience</div>}</div><div className="profile-activity">{profilePage.id===me?.id&&<ReferralCard notify={notify}/>}<h3>Activity</h3>{(profilePage.profilePosts||posts.filter((p:any)=>p.user===profilePage.id)).map((p:any)=>renderPost(p))}{!(profilePage.profilePosts||posts.filter((p:any)=>p.user===profilePage.id)).length&&<Empty icon={ImageIcon} title="Their story starts here." text="No posts yet."/>}{profilePage.activity?.length>0&&<><h3>Recent comments</h3>{profilePage.activity.map((a:any,i:number)=><div className="profile-comment" key={i}><MessageCircle size={15}/><div><p>{a.body}</p><small>{new Date(a.created+'Z').toLocaleDateString()}</small></div></div>)}</>}</div></div></>}
{page==='Notifications'&&<><section className="card activity-inbox"><h2>Notifications</h2>{activity.length?activity.map((n:any)=><div className="transaction" key={n.id}><Bell size={16}/><div><strong>{n.label}</strong>{n.gift_sender_username&&<small>From @{n.gift_sender_username}</small>}<small>{new Date(n.created+'Z').toLocaleString()}</small></div></div>):<p>No new activity yet.</p>}</section>{me&&<PushNotifications user={me.id}/>}<TradeRequests me={me} startChat={startChat}/></>}
{page==='Wallet activity'&&<WalletActivity back={()=>go('Wallet')}/>}
